int removeTargetVal_62(vector<int>& a, int val) { int k = 0; for (int i = 0; i < (int)a.size(); ++i) if (a[i] != val) a[k++] = a[i]; return k; }
void moveZeroesInPlace_62(vector<int>& a) { int slow = 0, n = a.size(); for (int fast = 0; fast < n; ++fast) if (a[fast] != 0) swap(a[slow++], a[fast]); }
bool isPalindromeScan_62(const string& s) { int lo = 0, hi = (int)s.size() - 1; while (lo < hi) { if (s[lo] != s[hi]) return false; ++lo; --hi; } return true; }
bool isSortedAscending_62(const vector<int>& a) { for (int i = 1; i < (int)a.size(); ++i) if (a[i] < a[i - 1]) return false; return true; }
vector<int> sortedSquaresMerge_62(const vector<int>& a) { int n = a.size(); vector<int> res(n); int lo = 0, hi = n - 1, p = n - 1; while (lo <= hi) { int s1 = a[lo] * a[lo], s2 = a[hi] * a[hi]; if (s1 > s2) { res[p--] = s1; ++lo; } else { res[p--] = s2; --hi; } } return res; }
vector<double> slidingWindowAverage_62(const vector<int>& a, int k) { int n = a.size(); vector<double> res; if (n < k || k <= 0) return res; double s = 0; for (int i = 0; i < k; ++i) s += a[i]; res.push_back(s / k); for (int i = k; i < n; ++i) { s += a[i] - a[i - k]; res.push_back(s / k); } return res; }
bool twoSumSortedTarget_63(const vector<int>& a, int target) { int lo = 0, hi = (int)a.size() - 1; while (lo < hi) { int s = a[lo] + a[hi]; if (s == target) return true; if (s < target) ++lo; else --hi; } return false; }
int twoSumLessThanK_63(const vector<int>& a, int k) { int lo = 0, hi = (int)a.size() - 1, best = -1; while (lo < hi) { int s = a[lo] + a[hi]; if (s < k) { if (s > best) best = s; ++lo; } else --hi; } return best; }
int containerMostWater_63(const vector<int>& h) { int lo = 0, hi = (int)h.size() - 1, best = 0; while (lo < hi) { int w = hi - lo; if (h[lo] < h[hi]) { int cur = h[lo] * w; if (cur > best) best = cur; ++lo; } else { int cur = h[hi] * w; if (cur > best) best = cur; --hi; } } return best; }
